function e(e,t,n,r=24){if(e.length<t||e.length>n)return`Gebruik ${t} tot ${n} spelers.`;let i=e.map(e=>e.normalize(`NFKC`).trim());return i.some(e=>e.length<2||e.length>r||/[\u0000-\u001f\u007f]/u.test(e))?`Gebruik voor elke speler een naam van 2 tot ${r} tekens.`:new Set(i.map(e=>e.toLocaleLowerCase(`nl-NL`))).size===i.length?null:`Gebruik voor iedereen een andere naam.`}export{e as t};